/**
 * Phase 34 — Native Android Video Editor (ClipForge) tests.
 *
 * The editor itself is Kotlin/Android code generated by
 * server/android/videoEditorGenerator.ts. These tests verify the
 * generated project structurally and semantically:
 * - it is a complete Phase 17 Android Studio project with Media3
 *   dependencies and no WebView anywhere;
 * - media import is picker-based (no storage permission) and probes
 *   metadata by streaming (MediaMetadataRetriever), never decoding
 *   whole files into memory;
 * - the Kotlin EditorOps implement the same operation set as the
 *   server engine's editingOps dispatcher;
 * - the Kotlin project model's JSON field names round-trip through
 *   the SERVER's own serializer/deserializer (interop proof);
 * - preview is ExoPlayer with per-clip clipping; export is Media3
 *   Transformer with progress polling and cancel();
 * - persistence (ProjectStore) and the SquadForge API client target
 *   the real Phase 31 endpoints;
 * - the generate route stores the project for the owning user only.
 *
 * Genuine Gradle compilation of the generated app is proven by the
 * Phase 34 CI workflow (scripts/phase34-genuine-build.ts) on a
 * GitHub-hosted runner, because this host cannot run the Gradle
 * daemon (documented environment limitation).
 */
import { test, describe, before, after } from 'node:test';
import assert from 'node:assert';
import http from 'node:http';
import { AddressInfo } from 'node:net';
import express from 'express';
import { db } from '../server/store.js';
import {
  generateVideoEditorProject,
  getVideoEditorConfig,
  MEDIA3_VERSION
} from '../server/android/videoEditorGenerator.js';
import { createAndroidRouter } from '../server/android/androidRoutes.js';
import {
  serializeVideoProject,
  deserializeVideoProject
} from '../server/videoEditor/timeline.js';
import type { VideoProject } from '../server/videoEditor/types.js';

const files = generateVideoEditorProject(getVideoEditorConfig());
const kt = (suffix: string): string => {
  const key = Object.keys(files).find(k => k.endsWith(suffix));
  assert.ok(key, `generated file ${suffix} missing`);
  return files[key!];
};

describe('Phase 34: generated project completeness', () => {
  test('is a complete Phase 17 project plus the editor sources', () => {
    for (const expected of [
      'settings.gradle.kts',
      'app/build.gradle.kts',
      'app/src/main/AndroidManifest.xml',
      'gradlew'
    ]) {
      assert.ok(files[expected], `missing ${expected}`);
    }
    kt('/MainActivity.kt');
    kt('/editor/EditorModels.kt');
    kt('/editor/EditorOps.kt');
    kt('/editor/ProjectStore.kt');
    kt('/editor/SquadForgeApi.kt');
    kt('/player/PreviewPlayer.kt');
    kt('/export/VideoExporter.kt');
    kt('/ui/EditorViewModel.kt');
    kt('/ui/EditorScreen.kt');
    kt('/EditorOpsTest.kt');
    assert.ok(files['VIDEO_EDITOR_README.md']);
  });

  test('app module depends on Media3 and the org.json test artifact', () => {
    const gradle = files['app/build.gradle.kts'];
    for (const artifact of ['media3-exoplayer', 'media3-transformer', 'media3-effect', 'media3-ui']) {
      assert.ok(gradle.includes(`androidx.media3:${artifact}:${MEDIA3_VERSION}`), artifact);
    }
    assert.ok(gradle.includes('testImplementation("org.json:json:20230618")'));
    // Media3 1.6.1 AAR metadata requires compileSdk 35 (CI run
    // 45649089150 failed at checkDebugAarMetadata with 34).
    assert.match(gradle, /compileSdk = 35/);
    assert.ok(files['gradle.properties'].includes('android.suppressUnsupportedCompileSdk=35'));
  });

  test('generated Kotlin has no broken multi-line string literals', () => {
    // Regression guard for CI runs 45665260288 and 45668710334:
    // single-backslash escapes in the generator's TS templates
    // turned "\n" inside Kotlin literals into real line breaks —
    // first in two string literals (captionsToSrt's cue separator,
    // EditorViewModel.kt export notes), then in two CHAR literals
    // ('\n' after the cue index and timestamp line), which a
    // double-quote-only scan cannot see. The scanner below is
    // escape- and comment-aware and tracks string AND char
    // literals; every literal must close on the line it opens.
    const unterminated = (content: string): number[] => {
      const bad: number[] = [];
      let inStr = false, inChar = false, inBlock = false, esc = false;
      content.split('\n').forEach((line, i) => {
        let inLineComment = false;
        for (let j = 0; j < line.length; j++) {
          const c = line[j], n = line[j + 1] ?? '';
          if (inLineComment) break;
          if (inBlock) { if (c === '*' && n === '/') { inBlock = false; j++; } continue; }
          if (esc) { esc = false; continue; }
          if ((inStr || inChar) && c === '\\') { esc = true; continue; }
          if (!inStr && !inChar) {
            if (c === '/' && n === '/') { inLineComment = true; break; }
            if (c === '/' && n === '*') { inBlock = true; j++; continue; }
            if (c === '"') inStr = true;
            else if (c === "'") inChar = true;
          } else if (inStr && c === '"') inStr = false;
          else if (inChar && c === "'") inChar = false;
        }
        if (inStr || inChar) { bad.push(i + 1); inStr = false; inChar = false; esc = false; }
      });
      return bad;
    };
    for (const [path, content] of Object.entries(files)) {
      if (!path.endsWith('.kt')) continue;
      assert.deepEqual(unterminated(content), [], `${path} has unterminated literals`);
    }
    // No generated Kotlin file may contain a triple quote: the
    // overlay label's escaped quotes once collapsed into """ in
    // EditorScreen.kt, which Kotlin reads as a raw-string opener
    // (CI run 45684916243: parser ran to EOF, "Expecting \"\"").
    for (const [path, content] of Object.entries(files)) {
      if (!path.endsWith('.kt')) continue;
      assert.ok(!content.includes('"""'), `${path} must not contain a raw-string opener`);
    }
    const screen = kt('/ui/EditorScreen.kt');
    assert.ok(screen.includes('"\\"" + text.text + "\\" @ "'), 'overlay label quotes the text');
    const ops = kt('/editor/EditorOps.kt');
    assert.ok(ops.includes('out.append(cue.text).append("\\n\\n")'));
    assert.ok(ops.includes("out.append(index + 1).append('\\n')"));
    const vm = kt('/ui/EditorViewModel.kt');
    assert.ok(vm.includes('"\\nNotes: "'));
  });

  test('manifest needs no storage permission (picker-based import)', () => {
    const manifest = files['app/src/main/AndroidManifest.xml'];
    assert.ok(manifest.includes('android.permission.INTERNET'));
    for (const forbidden of ['READ_EXTERNAL_STORAGE', 'READ_MEDIA_VIDEO', 'READ_MEDIA_IMAGES', 'READ_MEDIA_AUDIO', 'WRITE_EXTERNAL_STORAGE']) {
      assert.ok(!manifest.includes(forbidden), `manifest must not request ${forbidden}`);
    }
  });

  test('no WebView anywhere in the generated app', () => {
    for (const [path, content] of Object.entries(files)) {
      if (path.endsWith('.kt')) {
        assert.ok(!content.includes('WebView'), `${path} uses WebView`);
        assert.ok(!content.includes('android.webkit'), `${path} imports webkit`);
      }
    }
  });
});

describe('Phase 34: media import, preview, export wiring', () => {
  test('import uses the photo picker + document picker and persists grants', () => {
    const screen = kt('/ui/EditorScreen.kt');
    assert.ok(screen.includes('PickMultipleVisualMedia'));
    assert.ok(screen.includes('PickVisualMedia.ImageAndVideo'));
    assert.ok(screen.includes('OpenMultipleDocuments'));
    const vm = kt('/ui/EditorViewModel.kt');
    assert.ok(vm.includes('takePersistableUriPermission'));
    assert.ok(vm.includes('MediaMetadataRetriever'), 'metadata is probed, not decoded');
    // No whole-file loading of media anywhere in the app sources.
    for (const suffix of ['/ui/EditorViewModel.kt', '/player/PreviewPlayer.kt', '/export/VideoExporter.kt']) {
      const src = kt(suffix);
      assert.ok(!src.includes('readBytes()'), `${suffix} must not read whole files`);
      assert.ok(!src.includes('BitmapFactory.decodeStream'), `${suffix} must not decode media into memory`);
    }
  });

  test('preview is ExoPlayer over clipped playlist items', () => {
    const player = kt('/player/PreviewPlayer.kt');
    assert.ok(player.includes('ExoPlayer.Builder'));
    assert.ok(player.includes('ClippingConfiguration'));
    assert.ok(player.includes('setMediaItems'));
    const screen = kt('/ui/EditorScreen.kt');
    assert.ok(screen.includes('PlayerView'), 'preview surface is the Media3 PlayerView');
  });

  test('export is Media3 Transformer with progress and cancellation', () => {
    const exporter = kt('/export/VideoExporter.kt');
    assert.ok(exporter.includes('Transformer.Builder'));
    assert.ok(exporter.includes('.start(composition, outputFile.absolutePath)'));
    assert.ok(exporter.includes('transformer?.cancel()'));
    assert.ok(exporter.includes('getProgress(holder)'));
    assert.ok(exporter.includes('ExportCancelledException'));
    assert.ok(exporter.includes('Composition.Builder'));
    // Export limitations are stated in code, not hidden.
    assert.ok(exporter.includes('were not composited into the export'));
    assert.ok(exporter.includes('render as cuts'));
  });

  test('persistence saves atomically and recovers the last project', () => {
    const store = kt('/editor/ProjectStore.kt');
    assert.ok(store.includes('projects'));
    assert.ok(store.includes('.json.tmp'), 'writes go through a temp file');
    assert.ok(store.includes('renameTo'), 'temp file is renamed into place');
    assert.ok(store.includes('last_project.txt'));
    assert.ok(store.includes('loadLast'));
  });

  test('API client targets the real Phase 31 project endpoints', () => {
    const api = kt('/editor/SquadForgeApi.kt');
    assert.ok(api.includes('"/project/load"'));
    assert.ok(api.includes('"/project/save"'));
    assert.ok(api.includes('"/api/builds/"'));
    assert.ok(api.includes('HttpURLConnection'));
  });

  test('API client translates the SerializedVideoProject envelope both ways', () => {
    const api = kt('/editor/SquadForgeApi.kt');
    // Load: response.project is the envelope; the real project is
    // envelope.project and media must be merged back into it —
    // feeding the envelope to fromJson yields an empty project.
    assert.ok(api.includes('envelope.optJSONObject("project")'));
    assert.ok(api.includes('merged.put("media", envelope.optJSONArray("media")'));
    // Save: the body IS the envelope (format/version/project/media),
    // with media moved out of the project object.
    assert.ok(api.includes('payload.put("format", "squadforge-video-project")'));
    assert.ok(api.includes('payload.put("version", 1)'));
    assert.ok(api.includes('projectJson.remove("media")'));
    assert.ok(api.includes('payload.put("media", media)'));
  });
});

describe('Phase 34: editing-operation parity with the server engine', () => {
  test('Kotlin EditorOps cover the server dispatcher operations', () => {
    const ops = kt('/editor/EditorOps.kt');
    // Server editingOps.ts cases: addTrack, addClip, trim, split,
    // move, remove, setVolume, setSpeed, addText, updateText,
    // removeText, addTransition, setTrackVolume, setTrackMuted.
    for (const fn of [
      'fun addTrack', 'fun addClip', 'fun trimClip', 'fun splitClip',
      'fun moveClip', 'fun removeClip', 'fun setClipVolume',
      'fun setClipSpeed', 'fun addText', 'fun updateText',
      'fun removeText', 'fun addCaption', 'fun removeCaption',
      'fun addTransition', 'fun setTrackVolume', 'fun setTrackMuted'
    ]) {
      assert.ok(ops.includes(fn), `EditorOps missing ${fn}`);
    }
    // The generated app's own JVM tests ship with the project.
    const appTests = kt('/EditorOpsTest.kt');
    for (const name of ['addClipRejectsOverlap', 'splitProducesTwoClips', 'jsonRoundTripPreservesTheProject', 'srtFormattingMatchesTheServerShape']) {
      assert.ok(appTests.includes(name), `app test missing ${name}`);
    }
  });

  test('project JSON written by the Kotlin model parses in the server engine', () => {
    // A fixture with exactly the field names EditorModels.toJson()
    // emits (and fromJson reads).
    const fixture = {
      id: 'project_kotlin1',
      name: 'Kotlin Round Trip',
      width: 1280,
      height: 720,
      fps: 30,
      media: [
        { id: 'm1', path: 'content://media/video/1', durationSec: 12.5, hasVideo: true, hasAudio: true, width: 1920, height: 1080, kind: 'video' }
      ],
      tracks: [
        {
          id: 't1', kind: 'video', name: 'Video 1', volume: 1, clips: [
            {
              id: 'c1', mediaId: 'm1', trackStart: 0, sourceIn: 1, sourceOut: 6,
              volume: 0.8, effect: { type: 'none' }, speed: 1.5,
              transform: { x: 10, y: 20, scale: 1, rotationDeg: 0, opacity: 1 }
            }
          ]
        },
        { id: 't2', kind: 'audio', name: 'Audio 1', muted: false, clips: [] }
      ],
      transitions: [{ afterClipId: 'c1', type: 'crossfade', durationSec: 0.5 }],
      texts: [{ id: 'x1', text: 'Hello', trackStart: 1, durationSec: 2, x: 40, y: 40, fontSize: 48, color: '#FFFFFF' }],
      captions: [{ id: 'cap1', startSec: 0.5, endSec: 2.5, text: 'First line' }]
    };
    const parsed = deserializeVideoProject({ format: 'squadforge-video-project', version: 1, project: fixture, media: fixture.media } as any);
    assert.equal(parsed.project.name, 'Kotlin Round Trip');
    assert.equal(parsed.project.tracks[0].clips[0].speed, 1.5);
    assert.equal(parsed.project.texts?.[0].text, 'Hello');
    assert.equal(parsed.project.captions?.[0].text, 'First line');

    // And the server's serializer emits every field the Kotlin
    // fromJson reads.
    const serverProject: VideoProject = parsed.project;
    const out = serializeVideoProject(serverProject, parsed.mediaAssets) as any;
    for (const key of ['id', 'name', 'width', 'height', 'fps', 'tracks', 'media', 'transitions', 'texts', 'captions']) {
      assert.ok(key in out.project, `server serializer missing ${key}`);
    }
    const clip = out.project.tracks[0].clips[0];
    for (const key of ['id', 'mediaId', 'trackStart', 'sourceIn', 'sourceOut', 'volume']) {
      assert.ok(key in clip, `server clip missing ${key}`);
    }
  });
});

describe('Phase 34: generate route', () => {
  let owner: any;
  let foreigner: any;
  let build: any;
  let baseUrl: string;
  let server: http.Server;

  before(async () => {
    const stamp = Date.now();
    owner = { id: `usr_p34_${stamp}`, email: 'p34@squadforge.dev', name: 'P34 Owner' };
    foreigner = { id: `usr_p34f_${stamp}`, email: 'p34f@squadforge.dev', name: 'P34 Foreign' };
    db.saveUser(owner as any);
    db.saveUser(foreigner as any);
    build = {
      id: `bld_p34_${stamp}`,
      userId: owner.id,
      idea: 'ClipForge editor build',
      status: 'idle',
      progress: 0,
      logs: [],
      files: [],
      createdAt: stamp,
      updatedAt: stamp
    };
    db.saveBuild(build as any);

    const app = express();
    app.use(express.json());
    app.use((req: any, _res: any, next: any) => {
      req.user = req.headers['x-test-user'] === 'foreign' ? foreigner : owner;
      next();
    });
    const passAuth = ((_req: any, _res: any, next: any) => next()) as any;
    const verifyOwnership = (req: any, res: any, buildId: string) => {
      const found: any = db.getBuild(buildId);
      if (!found) {
        res.status(404).json({ error: 'Build not found' });
        return null;
      }
      if (found.userId !== req.user?.id) {
        res.status(403).json({ error: 'Forbidden' });
        return null;
      }
      return found;
    };
    app.use('/api/builds/:id/android', createAndroidRouter({ requireAuth: passAuth, verifyBuildOwnership: verifyOwnership as any }));

    server = http.createServer(app);
    const port = await new Promise<number>(resolve =>
      server.listen(0, '127.0.0.1', () => resolve((server.address() as AddressInfo).port))
    );
    baseUrl = `http://127.0.0.1:${port}`;
  });

  test('owner generates the editor project; files land in the build', async () => {
    const res = await fetch(`${baseUrl}/api/builds/${build.id}/android/video-editor/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({})
    });
    const body: any = await res.json();
    assert.equal(res.status, 200, JSON.stringify(body));
    assert.equal(body.success, true);
    assert.equal(body.editor, 'clipforge');
    assert.ok(body.generatedFilesCount >= 30, `expected the full project, got ${body.generatedFilesCount}`);
    const stored = db.getAllFiles(build.id) as any[];
    const paths = stored.map(f => f.path);
    assert.ok(paths.some(p => p.endsWith('/export/VideoExporter.kt')), 'exporter stored');
    assert.ok(paths.some(p => p === 'app/build.gradle.kts'), 'gradle stored');
  });

  after(() => {
    (server as any)?.closeAllConnections?.();
    server?.close();
  });

  test('foreign user cannot generate into someone else\'s build', async () => {
    const res = await fetch(`${baseUrl}/api/builds/${build.id}/android/video-editor/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-test-user': 'foreign' },
      body: JSON.stringify({})
    });
    assert.ok(res.status === 403 || res.status === 404, `foreign user got ${res.status}`);
  });
});
